<script setup lang="ts">
import { computed } from 'vue'
import { withBase } from 'vitepress'
import sources from '../diagrams/sources.json'

// Every SVG in .vitepress/theme/diagrams/ is loaded as raw text and inlined, so it
// can use the site's colour variables (light and dark mode). Generated by scripts/diagrams.py.
const files = import.meta.glob('../diagrams/*.svg', { query: '?raw', import: 'default', eager: true }) as Record<string, string>
const props = defineProps<{ name: string; caption?: string }>()
const links = computed(() => (sources as Record<string, { text: string; href: string }[]>)[props.name] ?? [])
const svg = computed(() => {
  const hit = Object.entries(files).find(([p]) => p.endsWith(`/${props.name}.svg`))
  return hit ? hit[1] : `<p>Missing diagram: ${props.name}</p>`
})
</script>

<template>
  <figure class="diagram">
    <div v-html="svg" />
    <figcaption v-if="caption">{{ caption }}</figcaption>
    <div v-if="links.length" class="sources">
      <strong>Sources:</strong>&nbsp;
      <template v-for="(l, i) in links" :key="l.href">
        <a :href="withBase(l.href)" target="_blank" rel="noopener noreferrer">{{ l.text }}</a><span v-if="i < links.length - 1" class="sep"> · </span>
      </template>
    </div>
  </figure>
</template>
